import java.io.*;
import java.util.*;

public class P1152D {

    public static void main(String[] args) {
        DataInputStream dis = new DataInputStream(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        try {
            int n = readInt(dis);
            int m = 2 * n;
            int[][] f = new int[m + 1][m + 2];
            f[0][0] = 1;
            long sum = 0;
            final int MOD = 1000000007;
            for (int i = 1; i <= m; i++) {
                f[i][0] = f[i - 1][1];
                for (int j = 1; j <= m; j++) {
                    f[i][j] = (f[i - 1][j - 1] + f[i - 1][j + 1]) % MOD;
                }
                if (i % 2 == 1) {
                    for (int j = 1; j + i <= m; j += 2) {
                        sum = (sum + f[i][j]) % MOD;
                    }
                }
            }
            pw.println(sum);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            pw.close();
        }
    }

    private static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        boolean neg = false;
        byte b = dis.readByte();
        while (b <= ' ') {
            b = dis.readByte();
        }
        if (b == '-') {
            neg = true;
            b = dis.readByte();
        }
        do {
            ret = ret * 10 + b - '0';
            b = dis.readByte();
        } while (b >= '0' && b <= '9');
        return neg ? -ret : ret;
    }
}
